const trig = $('When Executed by Another Workflow').item.json;

// --- Lead: soporta Airtable v1 (json.fields) y v2 (campos planos en json) ---
let lead={}, leadId=null;
try { const j=$('Airtable · Get Lead').first().json; if(j&&j.id){leadId=j.id; lead = j.fields ? j.fields : j;} } catch(e){}

// --- Asesores: idem ---
let asesores=[];
try { asesores=$('Airtable · Get Asesores').all().filter(a=>a.json&&a.json.id).map(a=>{const f=a.json.fields?a.json.fields:a.json; return {id:a.json.id, ...f};}); } catch(e){}

// ── FIX: Redis INCR devuelve { "rr:asesor:handoff:CAMP": N }, no { rr_counter: N }
let counter=1;
try {
  const rr = $('Redis · RR Counter').first().json;
  const vals = Object.values(rr).filter(v => !isNaN(Number(v)));
  if (vals.length) counter = Number(vals[0]) || 1;
} catch(e){}

// --- Sucursal destino (recId) ---
let sucRec=null; let sucNombre='';
try {
  const s=$('Airtable · Get Sucursal').all().map(i=>i.json).filter(r=>r&&r.id)[0];
  if(s){ sucRec=s.id; const f=s.fields?s.fields:s; sucNombre=f.nombre||''; }
} catch(e){}

// Guarda-espaldas: si el lead YA tiene sucursal guardada en el CRM, esa manda sobre
// el sucursal_id que mando el LLM (en ciudades con varias sucursales se equivoca).
const sucLead = (lead.sucursal_interes && lead.sucursal_interes[0]) || null;
let sucursalOverride = false;
if (sucLead && sucLead !== sucRec) { sucRec = sucLead; sucursalOverride = true; }

// --- Pool de candidatos ---
// OJO: el filtro por sucursal se hace en JS, NO con filterByFormula.
// ARRAYJOIN() de un campo link devuelve el PRIMARY (ej. "CAMP"), no el recId,
// y FIND("CAMP", "CAMP2") > 0 haria match cruzado entre las dos de Campeche.
// El API si devuelve el link como array de recIds, asi que comparamos contra eso.
// Criterio alineado con el SUB Auto-Asignar: `disponible` debe estar EXPLÍCITAMENTE
// en true. Un checkbox sin marcar llega como undefined; con `!== false` esos
// asesores entraban aquí y NO en Auto-Asignar, dando repartos distintos.
const disp = a => a.disponible === true;
let pool = sucRec ? asesores.filter(a => Array.isArray(a.sucursal) && a.sucursal.includes(sucRec) && disp(a)) : [];
let via = pool.length ? 'sucursal' : '';

// Degradacion elegante: sucursal sin asesores -> capacitacion -> cualquiera disponible.
if(!pool.length){
  pool = asesores.filter(a => String(a.asesor_id||'').trim().toUpperCase()==='CAP-LN');
  if(pool.length) via='fallback_capacitacion';
}
if(!pool.length){
  pool = asesores.filter(disp);
  if(pool.length) via='fallback_cualquiera';
}

// --- Cupo: max_leads_simultaneos ---
// Cuenta los leads con bot_paused=true (o sea, en manos de un humano) por asesor.
const carga={};
try {
  $('Airtable · Carga Actual Asesores').all().map(i=>i.json).filter(r=>r&&r.id).forEach(r=>{
    const f = r.fields ? r.fields : r;
    const aa = Array.isArray(f.asesor_asignado) ? f.asesor_asignado : [];
    aa.forEach(id => { carga[id]=(carga[id]||0)+1; });
  });
} catch(e){}

const conCupo = pool.filter(a=>{
  const max = Number(a.max_leads_simultaneos);
  if(!max || max<=0) return true;              // sin tope configurado = sin limite
  return (carga[a.id]||0) < max;
});
// Si TODOS estan al tope, no dejamos el lead sin dueno: se reparte igual y se marca.
if(conCupo.length) { pool = conCupo; }
else if(pool.length) { via = via + '+sobre_cupo'; }

// Orden estable: sin esto el round-robin depende del orden que devuelva Airtable.
pool.sort((a,b)=>String(a.asesor_id||'').localeCompare(String(b.asesor_id||'')));

// Continuidad: si el lead ya trae asesor y sigue en el pool, se respeta.
let asesor=null;
const prev=(lead.asesor_asignado&&lead.asesor_asignado[0])||null;
if(prev) asesor=pool.find(a=>a.id===prev)||null;
if(asesor) via = via + '+continuidad';
if(!asesor && pool.length) asesor = pool[(counter-1)%pool.length];

const asesorNombre=(asesor&&asesor.nombre)||'un asesor disponible';
const slackId=(asesor&&asesor.slack_id)||'';
const mention = slackId && !String(slackId).startsWith('REEMPLAZA') ? `<@${slackId}>` : asesorNombre;

const nombre = lead.nombre || trig.sender_name || 'Cliente';
const modelo = lead.modelo_interes || 'sin definir';
const resumen= lead.lead_summary || 'Sin resumen aun.';
const ciudad = lead.ciudad || 'desconocida';

// --- Perfil enriquecido (solo campos con valor) ---
const money = (n)=> (n!=null && n!=='' && !isNaN(Number(n))) ? '$'+Number(n).toLocaleString('en-US') : null;
const rows = [];
const push = (label,val)=>{ if(val!=null && String(val).trim()!=='' ) rows.push(`*${label}:* ${val}`); };
push('Temperatura', lead.temperatura);
push('Score', (lead.lead_score!=null?lead.lead_score:null));
push('Etapa', lead.etapa_pipeline);
push('Modelo de interés', modelo!=='sin definir'?modelo:null);
push('Categoría', lead.categoria_interes);
push('Uso', lead.uso_principal);
push('Forma de pago', lead.forma_pago_preferida);
push('Presupuesto', money(lead.presupuesto_declarado));
push('Enganche disponible', money(lead.enganche_disponible));
push('Última intención', lead.ultima_intencion);
push('Objeciones', lead.objeciones_detectadas);
push('Cómo llegó', lead.como_conocio);
push('Teléfono', lead.telefono);
push('Email', lead.email);
const perfil = rows.length ? rows.join('\n') : '_Sin datos de perfil aún._';

// Horario humano RM: L-V 9-18:30, Sab 9-14:30 (Yucatan UTC-6 fijo).
const now=new Date(); const mx=new Date(now.getTime()-6*3600*1000);
const dow=mx.getUTCDay(), hour=mx.getUTCHours();
let dentro=false;
if(dow>=1&&dow<=5) dentro = hour>=9 && hour<19;
else if(dow===6) dentro = hour>=9 && hour<15;
const notaHorario = dentro ? '' : '\n:crescent_moon: *Fuera de horario* — el cliente fue avisado de que responden al abrir.';

const chatUrl = `https://cwrivasmotors.lexnova.cloud/app/accounts/1/conversations/${trig.conversation_id||''}`;

const slack_text =
`:fire: *Lead para atención — Rivas Motors*
*Cliente:* ${nombre} (${trig.user_id_canal})
*Ciudad:* ${ciudad}   *Sucursal:* ${sucNombre || trig.sucursal_id || 's/d'} (${trig.sucursal_id||'s/d'})
*Motivo:* ${trig.reason||'no especificado'}
*Prioridad:* ${trig.priority||'media'}
*Asesor asignado:* ${asesorNombre}${via && via!=='sucursal' ? ' _(' + via + ')_' : ''}

*— Perfil del lead —*
${perfil}

*Resumen:* ${resumen}
:link: <${chatUrl}|Abrir chat en Chatwoot>
:white_check_mark: _Cuando termines, *resuelve* la conversación en Chatwoot y el bot retoma._${notaHorario}
${mention}`;

// --- Texto del DM al asesor (sin la mención: ya le llega directo) ---
const dm_text =
`:fire: *Te asignaron un lead que pide atención*
*Cliente:* ${nombre}
*WhatsApp:* <https://wa.me/${String(trig.user_id_canal||'').replace(/[^0-9]/g,'')}|${trig.user_id_canal}>
*Sucursal:* ${sucNombre || trig.sucursal_id || 's/d'}
*Motivo:* ${trig.reason||'no especificado'}
*Prioridad:* ${trig.priority||'media'}

*— Perfil del lead —*
${perfil}

*Resumen:* ${resumen}
:link: <${chatUrl}|Abrir chat en Chatwoot>
:warning: _El agente ya está pausado: la conversación es tuya. Cuando termines, *resuelve* la conversación en Chatwoot y el bot retoma._${notaHorario}`;

const aviso_cliente = dentro
  ? `¡Gracias por tu interés! 🙌 En un momento *${asesorNombre}* se pondrá en contacto contigo para atenderte personalmente.`
  : `¡Gracias por tu interés! 🙌 En cuanto abramos, *${asesorNombre}* se pondrá en contacto contigo para atenderte personalmente.`;

return [{ json: {
  ok:true, via, pool_size: pool.length, sucursal_override: sucursalOverride, carga_asesor: (asesor && carga[asesor.id]) || 0, sucursal_rec: sucRec, user_id_canal:trig.user_id_canal, lead_id:leadId,
  asesor_id: asesor?asesor.id:null, asesor_nombre:asesorNombre,
  chatwoot_agent_id: (asesor && asesor.chatwoot_agent_id) || null,
  dentro_horario:dentro, slack_text, dm_text, aviso_cliente,
  asesor_slack_id: slackId, tiene_slack: (!!slackId && !String(slackId).startsWith('REEMPLAZA'))
}}];
